package com.farmdirect.controller;
import com.farmdirect.dao.ProductDAO;import com.farmdirect.model.*;import javax.servlet.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import java.io.IOException;import java.util.*;
@WebServlet("/cart") public class CartServlet extends HttpServlet{
 @SuppressWarnings("unchecked") private Map<Integer,Integer> cart(HttpServletRequest q){Map<Integer,Integer> c=(Map<Integer,Integer>)q.getSession().getAttribute("cart");if(c==null){c=new LinkedHashMap<>();q.getSession().setAttribute("cart",c);}return c;}
 protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{try{Map<Integer,Integer> c=cart(q);List<Map<String,Object>> items=new ArrayList<>();double total=0;ProductDAO d=new ProductDAO();for(Map.Entry<Integer,Integer> e:c.entrySet()){Product x=d.find(e.getKey());if(x!=null){Map<String,Object> m=new HashMap<>();m.put("product",x);m.put("quantity",e.getValue());m.put("subtotal",x.getPrice()*e.getValue());items.add(m);total+=x.getPrice()*e.getValue();}}q.setAttribute("items",items);q.setAttribute("total",total);q.getRequestDispatcher("cart.jsp").forward(q,p);}catch(Exception e){throw new ServletException(e);}}
 protected void doPost(HttpServletRequest q,HttpServletResponse p)throws IOException{try{Map<Integer,Integer> c=cart(q);String action=q.getParameter("action");int id=Integer.parseInt(q.getParameter("id"));if("remove".equals(action))c.remove(id);else{int qty=Math.max(1,Integer.parseInt(q.getParameter("quantity")));c.put(id,qty);}p.sendRedirect("cart");}catch(Exception e){p.sendRedirect("cart");}}
}